fixture=root/'src/data/fixtures.json'
entries=json.loads(fixture.read_text())
by_path={entry['path']:entry for entry in entries}
stamp=datetime.datetime.now(datetime.UTC).isoformat()
def p(value):return '<p>'+html.escape(value)+'</p>'
def link(path):
    title=by_path[path]['title'] if path in by_path else next((x['title'] for x in lessons if x['path']==path),None)
    assert title is not None,path
    return '<a href="/'+html.escape(path,quote=True)+'">'+html.escape(title)+'</a>'
hubs=[
 dict(path='web-tech/authorization-and-tenant-boundaries',title='Authorization and Tenant Boundaries',summary='Enforce each action on its actual record and carry tenant scope through caches, workers, and exports.',overview='A signed-in user is not automatically allowed to read or change every record an endpoint accepts. Authorization has to combine the actor, action, record, and current organizational scope at the server boundary. Lists, files, queued work, and caches need the same constraint. This track follows a case-review application with several tenant organizations and changing reviewer assignments. It tests denial as carefully as allowed access, including after role changes and account switching.',bridges=['web-tech/identity-and-application-security','web-tech/search-permissions-and-private-results','web-tech/shared-cache-keys-and-private-response-boundaries']),
 dict(path='web-tech/data-retention-export-and-erasure',title='Data Retention, Export, and Erasure',summary='Track where private data persists and make export, expiry, and deletion outcomes verifiable.',overview='A data record does not live in one database row. Copies can appear in search indexes, cached responses, browser storage, export artifacts, worker queues, logs, and backups. A deletion action that removes only the primary row may leave several usable copies. This track maps those stores, ties each copy to a retention purpose, treats export and erasure as authorized jobs, and prevents old backups from resurrecting deleted records. Product and legal policy set actual retention periods; the lessons focus on the engineering contracts needed to implement and verify those decisions.',bridges=['web-tech/browser-security-and-data-stewardship','web-tech/backup-restore-drill','web-tech/large-export-download-and-integrity'])
]
lessons=[
 dict(hub=0,path='web-tech/object-level-authorization-for-reads-and-writes',title='Object-Level Authorization for Reads and Writes',summary='Check actor, action, and current record scope for every read or mutation, including list membership.',definition='Object-level authorization decides whether an authenticated actor may perform a specific action on a specific record now. Route access alone cannot answer it: the same endpoint may serve records owned by different organizations or assigned to different reviewers. Derive the actor from a verified session, load or query the target under the permitted scope, and deny when the relationship does not match. Apply the same policy to detail reads, updates, deletes, comments, and bulk item IDs. A random-looking record ID helps avoid casual guessing but is not an authorization rule. Collection endpoints must constrain rows before pagination and aggregation, not filter unauthorized results after counting them.',case='Reviewer 29 may view case 47 in organization 6 but not case 62 in organization 9. Both use the same detail URL shape. A client changes the case number in a request, then tries the update endpoint and a bulk export. The server must deny each cross-scope action even if a navigation menu never displayed the other case. A list query for Open cases should include only authorized rows before its count and cursor are calculated. If case 47 is reassigned while the page remains open, the next save must use current authorization rather than the permission observed at page load.',code='function mayReview(actor, record) {\n  return actor.tenantId === record.tenantId && record.reviewerIds.includes(actor.userId);\n}\nconsole.log(mayReview({ tenantId: 6, userId: 29 }, { tenantId: 9, reviewerIds: [29] }));\n// Output: false',implementation='The predicate illustrates a policy decision, not a complete endpoint. Run it with server-trusted actor context and current record state, preferably within a data access pattern that cannot first expose the row. For a write, authorize the requested action and validate the record version in the same transaction or an equivalent atomic condition. A bulk request must authorize every item, then define whether unauthorized items reject the whole operation or are reported individually without leaking their contents. Ensure a search index and count endpoint enforce the same scope. Test a valid actor, a same-tenant unassigned actor, a foreign-tenant actor, and a role change.',cost='A policy check can be O(1) when membership and tenant keys are indexed, but a careless per-row authorization lookup turns a list of n records into n extra queries. Push scope into the database query or batch the relation lookup, then verify the query plan under realistic page sizes. Filtering after pagination can yield sparse pages, incorrect counts, and information leaks. Cached policy decisions save work but make revocation slower; use short lifetimes or a permission version when access can change quickly. Measure both denial correctness and query cost.',failure='The API checks only that the caller has a reviewer role, then loads any case by numeric ID. Reviewer 29 requests case 62 and sees a private note from organization 9. Hiding the case in the UI did nothing. Add a server-side object constraint and test direct requests. Another failure filters the first fifty search hits after fetching them; the response contains only three visible hits but reveals that dozens of hidden cases matched. Constrain the index query or authorized result set before ranking, count, and cursor generation.',drill='Create two organizations, two reviewers, and cases 47 and 62. Test detail GET, PATCH, delete, search count, cursor page, and a bulk action with mixed authorized IDs. Reassign case 47 between read and write and ensure the old editor cannot save. Test that a foreign record ID does not reveal its title, status, or whether it exists beyond the chosen response contract. Record database query count for a fifty-row page and ensure permission checks do not create one query per row.',decision='Authorize the current action on the current object at the server and constrain collections before counting or paging.',checks=['Direct ID changes cannot reveal or mutate a foreign record.','List counts and cursors derive from authorized rows.','Revocation between read and write blocks the stale writer.'],mistakes=['Treating a signed-in reviewer role as permission for every case.','Relying on unguessable IDs or hidden links as access control.','Filtering protected rows only after pagination.'],related=['web-tech/search-permissions-and-private-results','web-tech/conditional-writes-and-lost-update-prevention','web-tech/identity-and-application-security']),
 dict(hub=0,path='web-tech/tenant-scope-in-cache-and-background-work',title='Tenant Scope in Cache and Background Work',summary='Carry verified tenant identity into caches, messages, and workers without accepting a client claim as authority.',definition='Multi-tenant applications share code and often share storage, but each tenant remains a security boundary. A verified session selects the active tenant; a request body or URL may identify a target but cannot self-authorize a tenant switch. Database predicates, cache keys, queue messages, file paths, and search documents must keep scope explicit. A cache key that omits tenant identity may return one organization’s record to another even when the database query was correct. Background jobs are more subtle: a worker may have broad service access, so it must re-establish the actor and tenant scope from a trusted job envelope and restrict every object it touches.',case='Organizations 6 and 9 both have a case numbered 47. The API caches case summaries by the string case:47. Reviewer 29 from organization 6 loads a summary, then reviewer 62 from organization 9 receives the cached one. A later export worker receives tenantId 9 in a client-submitted payload and reads organization 9 data despite the requester belonging to 6. Fixing only the cache key is insufficient. Derive tenant scope from the authenticated actor when enqueueing, bind the job to that actor and authorized tenant, and check the same boundary when the worker executes.',code='function caseCacheKey(tenantId, caseId, permissionVersion) {\n  return `tenant:${tenantId}:case:${caseId}:policy:${permissionVersion}`;\n}\nconsole.log(caseCacheKey(6, 47, 3));\n// Output: tenant:6:case:47:policy:3',implementation='A scoped cache key prevents one class of collision, but authorization must run before protected cache reads. Include all attributes that alter the representation, such as user role or permission version, or do not cache that representation across users. Keep globally shared assets in a separate explicit namespace. Build job envelopes on the server after authorization; record requester and permitted tenant as server-authored metadata, and require workers to use tenant-scoped data access. Privileged maintenance jobs need a distinct audited path. If database row-level controls are used, connect normal requests with a role that cannot bypass them and set tenant context safely for each transaction.',cost='Adding a tenant dimension increases cache entries roughly with the number of active tenants and may lower hit rate, but it prevents cross-tenant reuse. Permission-version dimensions can create stale entries until eviction, so TTL and invalidation still matter. Tenant predicates need indexes for common access patterns; without them, shared tables scan more rows as tenant count grows. A worker check adds small per-job cost compared with the cost of a data leak. Load-test mixed-tenant traffic, not only one tenant at a time, and measure cache hit rate and query plans.',failure='A developer patches the API cache key but leaves an image variant cache keyed only by image ID. A user who guesses a path can retrieve another tenant’s file from the edge. Inventory every store and delivery path, then scope or authorize each. Another defect trusts tenantId copied from an API request into a job; the worker runs with a privileged database role and bypasses the endpoint’s restriction. Construct the job envelope from verified server state, make the worker enforce scope, and test a forged tenant field.',drill='Create tenant 6 and tenant 9 records with the same case ID. Alternate requests rapidly and inspect API, search, media, and edge-cache results. Submit a forged tenantId in an export request and verify the server ignores or rejects it. Replay a queued job after the requester loses access; define whether it continues under an already authorized immutable grant or rechecks current permission, and test the chosen rule. Check database sessions and worker identities for privileges that bypass normal tenant predicates.',decision='Make tenant scope server-derived and explicit in every storage, cache, and background boundary.',checks=['Same numeric IDs in separate tenants never share protected cache entries.','Workers reject forged or stale tenant claims according to a documented policy.','Normal request paths cannot silently bypass tenant-scoped database access.'],mistakes=['Assuming tenant IDs are globally unique object IDs.','Using a tenant-aware database query behind a tenant-blind cache key.','Letting a privileged worker trust tenant scope from client payload.'],related=['web-tech/shared-cache-keys-and-private-response-boundaries','web-tech/background-jobs-and-outbox','web-tech/search-permissions-and-private-results']),
 dict(hub=0,path='web-tech/permission-revocation-and-active-sessions',title='Permission Revocation and Active Sessions',summary='Make role and assignment changes take effect across sessions, caches, live streams, and queued work.',definition='Permissions change while sessions remain active. A user may lose a role, leave a tenant, or be removed from a case. A signed session proves identity but need not carry fresh authorization forever. Choose a revocation model: server lookups on sensitive actions, a permission-version check, short-lived grants with refresh, or a combination. The required delay depends on the data risk. Client UI should hide actions after refresh, yet the server must reject revoked access immediately or within a clearly defined bounded window. Live streams, cached private responses, and queued exports require explicit invalidation or rechecks.',case='Reviewer 29 is removed from organization 6 during an open editing session. The browser still shows case 47 and an already connected event stream. A stale role claim in a long-lived token would let the user save or continue receiving notes. The API checks the current permission version for each sensitive request, the live channel closes or filters messages when membership changes, and private browser caches are cleared on account switch. An export job accepted before revocation follows a documented policy: it either stops before artifact creation or completes only for an already authorized, short-lived recipient grant.',code='function grantIsCurrent(session, account) {\n  return session.permissionVersion === account.permissionVersion && session.tenantId === account.tenantId;\n}\nconsole.log(grantIsCurrent({ permissionVersion: 3, tenantId: 6 }, { permissionVersion: 4, tenantId: 6 }));\n// Output: false',implementation='The version comparison is a simple model; run it against trusted current account state. Increment a permission version when role or membership changes and make sensitive requests compare it before reading protected data. If checking central state for every static request is too expensive, separate public assets from private actions and bound the refresh interval deliberately. Close or reauthorize subscriptions after membership changes. Invalidate caches that vary by role, deny old signed download grants when feasible, and document queued-job behavior. A tab notification helps clear local data promptly but cannot replace server enforcement, since the tab may be asleep or offline.',cost='A central version lookup can add O(1) read work to each protected request and can become a hot path under high traffic. A short-lived cache reduces reads but extends the revocation delay by its lifetime. Streaming connections need periodic or event-driven permission reevaluation; frequent checks cost more but limit unauthorized data after removal. The number of cached variants also grows with permission versions until expiry. Measure the longest observed revocation delay from admin action to denied read, write, live event, and download—not only the time until buttons disappear.',failure='An administrator removes reviewer 29, and the visible button vanishes after a refresh, but an old tab can still POST to the API with a stale signed role claim. Frontend removal is not a policy change. The server must reject the request. Another failure clears API cache yet leaves a live event stream delivering private updates for an hour. Test revocation against every channel and artifact. Do not assume a broadcast message reaches suspended tabs; permission checks must remain server-owned.',drill='Open two tabs and a live stream for reviewer 29, then remove the reviewer from organization 6. Time the first denied detail read, update, stream event, and artifact download. Keep one tab suspended and retry on wake. Start an export immediately before revocation and verify its documented continuation rule. Re-add the reviewer with a new permission version and check that old cache entries are not reused across the change. Include a second tenant to prove tenant switching cannot revive stale grants.',decision='Bound authorization staleness on the server and test revocation across every private delivery channel.',checks=['A revoked user cannot write with an old active session.','Live and cached private data stop after the defined revocation bound.','Queued jobs and downloads have an explicit revocation rule.'],mistakes=['Treating hidden controls as permission enforcement.','Keeping long-lived role claims without a freshness check.','Forgetting live streams and export artifacts during revocation.'],related=['web-tech/account-recovery-and-session-revocation','web-tech/live-update-reconnect-and-order','web-tech/cross-tab-invalidation-and-version-checks']),
 dict(hub=0,path='web-tech/private-export-authorization-and-artifact-scope',title='Private Export Authorization and Artifact Scope',summary='Keep export jobs and download artifacts bound to requester, tenant, filter, and expiry.',definition='A private export is a delayed read over many records. Authorization at the button click is only the first boundary. The server must authorize the requested scope before enqueueing, and the worker must load only permitted records when producing the artifact. The final download requires a separate access check or a short-lived grant bound to a specific artifact and recipient. A status endpoint must not reveal another user’s export name, row count, or progress. Artifact IDs should be opaque but opacity does not replace checks. Temporary objects, CDN caches, and range requests need the same privacy rules as the original data.',case='Reviewer 29 requests an export of 62 cases in organization 6. Before the worker starts, the reviewer loses membership. The product’s chosen rule is to cancel pending generation and mark the request Denied without exposing counts. A different approved policy could retain a narrow immutable grant, but it must be explicit and time-limited. The artifact, if produced, carries tenant, requester, filter, creation time, and expiration metadata. Reviewer 62 from organization 9 cannot obtain it by guessing its ID or changing a status URL. A public cache cannot store its response.',code='function mayDownload(actor, artifact, now) {\n  return actor.userId === artifact.requesterId && actor.tenantId === artifact.tenantId && now < artifact.expiresAt;\n}\nconsole.log(mayDownload({ userId: 29, tenantId: 6 }, { requesterId: 29, tenantId: 9, expiresAt: 80 }, 47));\n// Output: false',implementation='The predicate illustrates scope; the server must verify current policy or a narrowly minted grant before returning bytes. Store the exact normalized filter and tenant with the job, then bind the worker query to them. Exports should avoid embedding a broad service credential in a user-visible URL. A signed URL, when used, needs a short expiry and artifact-specific scope, with a plan for revocation and logging. Set private response caching headers, control CDN behavior, and validate range resume against the same immutable artifact. Delete expired artifacts and job metadata under a retention schedule. Treat unauthorized status and download requests consistently without revealing artifact existence unnecessarily.',cost='Export generation is at least O(n) in the number of included records and may require O(b) temporary storage for b output bytes. Rechecking policy adds limited work compared with scanning or serializing a large dataset. Short artifact TTLs reduce exposure and storage but can frustrate slow downloads; range support requires immutable bytes and validator handling. Encrypting and storing each artifact has operational cost, especially if multiple tenants request similar filters. Measure artifact count, unauthorized attempts, expiry cleanup lag, and bytes served from a private cache path.',failure='The job endpoint checks tenant scope, but the worker runs a query using only the date range and exports cases from all organizations. A later status page exposes the total count to anyone with the job ID. Scope the worker query and status route independently. Another failure sends the artifact through a public CDN with a URL that lives for a week. Guessing the URL is not the only risk; links can appear in logs, browser history, or referrers. Keep grants narrow and short-lived, and test cache behavior with two accounts.',drill='Request an organization-6 export, then forge organization 9 in the job payload. Inspect worker query parameters and generated rows. Change membership between request and worker start, and verify the chosen revocation policy. Have another user request status and download using the artifact ID; neither may reveal content or metadata. Test artifact expiry, private cache headers, range resume across revisions, and deletion of temporary files after failure. Verify a failed worker leaves no partially downloadable artifact labeled complete.',decision='Authorize export request, worker query, status, and download as separate private boundaries.',checks=['A forged filter or tenant cannot widen the worker result set.','Another account cannot infer private status or retrieve an artifact by ID.','Expired or revoked artifacts have a verified cleanup path.'],mistakes=['Authorizing only the initial export button.','Assuming an opaque artifact ID is enough protection.','Putting a private artifact behind public caching.'],related=['web-tech/large-export-download-and-integrity','web-tech/search-permissions-and-private-results','web-tech/accepted-operations-and-status-resources']),
 dict(hub=1,path='web-tech/retention-inventory-and-expiry-workflows',title='Retention Inventory and Expiry Workflows',summary='Map every copy of a private record and make expiry observable across primary and derived stores.',definition='Retention is a data-flow property, not a single database TTL. The same case note may exist in primary rows, search documents, image variants, browser caches, analytics events, export artifacts, worker messages, and backups. Start with an inventory naming each store, the purpose of its copy, owner, access scope, and approved retention period. Policy and law set the periods; implementation should not invent them. Each expiring copy needs a deletion or irreversible de-identification path, and derived stores need a way to learn that the source record changed or expired. Keep a small non-sensitive completion record so operators can prove the workflow ran without retaining the deleted content.',case='Case 47 reaches an approved retention boundary. The primary row is removed, but its title remains in the search index and a 740 MB export persists in object storage. A reviewer can no longer open the case page yet still finds it in autocomplete. The expiry workflow first prevents new access, records the target and policy version, queues cleanup for search, media, exports, and caches, then verifies each target. A failed index deletion becomes a visible retryable task rather than a quiet success. Backup expiry follows a separate schedule and restore process.',code='function expiredAt(now, deadline) {\n  return Number.isFinite(deadline) && now >= deadline;\n}\nconsole.log(expiredAt(93, 62));\n// Output: true',implementation='The helper only decides a deadline. A production inventory should list every copy and specify how a record key maps to it. Run expiry with a stable deletion operation ID; retries must not recreate a record or treat missing rows as failure when they were already removed. Prevent reads during multi-store cleanup with a tombstone or access gate, then fan out bounded cleanup tasks. Verify each store and keep a minimal outcome record with no original note. If a store cannot delete promptly, document its restricted access and deadline. Ensure new search-index rebuilds and exports honor tombstones, not only live row absence.',cost='Scanning n records for expiry is O(n) without an index or scheduled partition; an indexed deadline query can fetch due rows proportionally to the due set. Each deletion fans out to k derived stores, making total work O(k) per record before backup handling. Keeping tombstones uses storage but prevents reappearance during asynchronous cleanup and restore. Aggressive polling raises load; large intervals extend the period between deadline and completed cleanup. Measure due backlog, oldest overdue item, retry count, and per-store completion rather than only counting primary-row deletions.',failure='A database TTL removes case 47. The search index still returns its title and an old export remains downloadable. The team considered deletion complete because the primary query returns 404. Define completion across stores and gate reads while cleanup proceeds. Another failure lets a nightly index rebuild replay old change events after a deletion, resurrecting a searchable document. Carry a deletion generation or tombstone through the rebuild and test replay order. Do not put full private content into the cleanup log just to make the operation auditable.',drill='Inventory every location reached by a case note and its attachment. Expire case 47, deliberately fail search deletion, and confirm the case is inaccessible while the cleanup task remains visible. Retry the task, rebuild the index from a stale event stream, and check that the document does not return. Inspect the export artifact and browser cache paths. Run the same operation twice and verify it is safe. Report completion only after every active derived store meets its policy, while recording backup handling separately.',decision='Treat retention as a mapped multi-store workflow with read gating, retries, and store-level evidence.',checks=['Every active copy has an owner, purpose, retention decision, and cleanup path.','An index or artifact failure cannot be reported as complete expiry.','Rebuilds cannot revive a tombstoned record.'],mistakes=['Equating primary-row deletion with complete expiry.','Ignoring derived search and export copies.','Writing the deleted private content into cleanup evidence.'],related=['web-tech/search-index-freshness-and-rebuilds','web-tech/telemetry-minimization-and-retention','web-tech/background-jobs-and-outbox']),
 dict(hub=1,path='web-tech/export-and-erasure-job-state',title='Export and Erasure Job State',summary='Represent data requests as authorized jobs with terminal evidence and recoverable failure states.',definition='A user-data export or erasure request can span several systems and take longer than one HTTP response. Model it as an authorized operation with states such as accepted, checking, running, partially failed, complete, and rejected. The initial response means the request was accepted, not that an export is downloadable or erasure finished. Keep the requester, target scope, operation ID, policy version, and audit timestamps as minimal job metadata. A status endpoint must be private. Terminal success should require verified target results; a worker crash, missing connector, or unresolved exception must remain visible and retryable. Human review requirements depend on the organization’s policy and should be explicit in the job.',case='A user asks to erase case 47 and download an account export. The API returns two job IDs. The export waits while a snapshot of permitted records is assembled; a Ready state gives a short-lived download path. The erasure job marks the case inaccessible, removes active copies, and waits for checks from search and object storage. Search cleanup fails once. The status remains Partially failed, with a retry action for an operator, instead of telling the user everything is gone. A second identical request uses the same intent identity or an explicit new request, avoiding duplicate cleanup side effects.',code='function completionState(targets) {\n  if (targets.every(item => item === "done")) return "complete";\n  return targets.some(item => item === "failed") ? "partial-failure" : "running";\n}\nconsole.log(completionState(["done", "failed", "done"]));\n// Output: partial-failure',implementation='The function illustrates aggregation, while a real workflow records per-store attempts, retry bounds, and verified results. Authenticate the requester and authorize the target before creating the job. Separate export and erasure grants; a user may be entitled to one but not the other. Use idempotent worker steps and a stable operation ID so a lost response does not duplicate destructive actions. Avoid exposing exact private record counts to an unauthorized status caller. Choose a terminal response that reflects the approved policy and include known limitations, such as backup expiration timing, rather than claiming immediate physical erasure of every byte. Keep only the minimal completion evidence required by policy.',cost='A job touching k stores requires at least O(k) orchestration and verification work plus O(n) processing for n included records. Parallel cleanup reduces elapsed time but can overload downstream systems; a bounded queue and per-store retry budget contain that cost. Detailed per-item logs may expose private data and grow O(n), so aggregate evidence by store and operation where possible. An export can consume large temporary storage and must expire. Measure time to terminal state, partial-failure backlog, retry count, cleanup lag, and unauthorized status attempts.',failure='The erasure endpoint returns 200 immediately after placing a queue message, and the UI says Deleted. The queue is down, so nothing was removed. Return an accepted operation state and report terminal completion only after checks. Another defect lets anyone who knows a job ID see that the user has 62 private records. Authorize status and minimize exposed metadata. If a worker repeatedly fails, retain a visible partial-failure state with an owner and next action; neither infinite silent retries nor false success meets the contract.',drill='Submit authorized export and erasure requests for case 47. Cut the queue after acceptance, then restart it; confirm stable operation IDs and no duplicate cleanup. Fail one search-index step and verify Partially failed status while reads stay gated. Request the status from another account and inspect that no private count leaks. Complete all active-store checks, download the export once through an expiring grant, and verify temporary artifact cleanup. Record how a backup restore will respect the deletion marker before declaring the full policy outcome.',decision='Treat export and erasure as private operations with explicit per-store evidence and honest terminal states.',checks=['An accepted response never claims the multi-store job is complete.','Partial failure has a visible owner and retry path.','Status and artifact access enforce requester and target scope.'],mistakes=['Showing Deleted when only a message was enqueued.','Treating a job ID as authorization for status or download.','Discarding evidence of a failed downstream cleanup step.'],related=['web-tech/accepted-operations-and-status-resources','web-tech/large-export-download-and-integrity','web-tech/retention-inventory-and-expiry-workflows']),
 dict(hub=1,path='web-tech/backup-restore-with-deletion-tombstones',title='Backup Restore with Deletion Tombstones',summary='Prevent old snapshots from reviving data that was removed after the backup was taken.',definition='A backup captures an earlier data state. Restoring it can revive records deleted after that snapshot unless deletion decisions are preserved separately and replayed during recovery. A tombstone records that a scoped object must remain unavailable, with an operation generation or sequence that can be compared against restored data. The restore plan must account for primary rows, indexes, files, and queued change events. Backups also have their own expiry schedule; deleting a live record does not imply every historical backup block vanishes immediately. The application must describe the approved policy accurately and restrict backup access while it ages out.',case='A nightly snapshot contains case 47. The next day an erasure operation removes it from active stores and records deletion generation 8. Two days later an outage requires restoring the old snapshot. Without the tombstone, case 47 reappears in the database, and an index rebuild makes it searchable. The recovery process imports the snapshot into a controlled environment, applies all later deletion markers before serving users, then rebuilds derived stores only from permitted records. A smoke check confirms case 47 remains inaccessible while case 62, which was not deleted, is restored.',code='function mayRestore(recordGeneration, deletionGeneration) {\n  return deletionGeneration === undefined || recordGeneration > deletionGeneration;\n}\nconsole.log(mayRestore(6, 8));\n// Output: false',implementation='The numeric helper expresses ordering, not a complete restore protocol. Keep deletion markers in a recoverable store whose retention outlives any backup that may contain the record. Bind markers to tenant and stable object identity; recycled IDs must not confuse them. During restore, do not reopen traffic until the snapshot, later writes, and deletion markers are reconciled. Rebuild search and media indexes from the reconciled state, and validate queued events do not recreate deleted rows. Test a single-tenant recovery separately from a global restore, because shared backups may require selective recovery without exposing other tenant data.',cost='Replaying d deletion markers after a restore is O(d) work plus verification across k derived stores. Holding markers longer than the oldest relevant backup consumes storage but is usually far smaller than retaining full deleted content. A restore into a separate environment adds temporary storage and time, yet permits checks before users see the data. Rebuilding large indexes may dominate recovery time. Measure recovery point, recovery time, marker replay duration, and post-restore unauthorized hits; a successful database boot is not enough evidence.',failure='The team restores a clean-looking database snapshot from Monday and turns traffic on immediately. Case 47, deleted Tuesday, becomes visible again on Thursday, while a queued index event republishes its title. A restore plan without deletion replay has violated the active deletion decision. Keep a marker ledger and test it in drills. Another failure deletes the markers after thirty days while backups remain available for ninety; a late restore then has no memory of removed records. Align marker and backup lifetimes under the approved policy.',drill='Take a backup containing cases 47 and 62. Delete case 47, create marker generation 8, then restore the old snapshot into an isolated environment. Apply the markers, rebuild the index, and test both cases before opening traffic. Delay an old add event until after rebuild and ensure it cannot revive case 47. Try a tenant-6-only restore from a shared backup and check that tenant 9 remains inaccessible. Verify marker retention covers the oldest backup that could contain the deleted record.',decision='Reconcile deletion markers before restored data or derived indexes become readable.',checks=['A restored snapshot cannot re-expose a later-deleted record.','Marker retention covers every backup that may contain the record.','Index and queue replay honor deletion generations.'],mistakes=['Treating backup restore as a simple database replacement.','Expiring tombstones before old backups expire.','Opening traffic before rebuilt indexes and deletions are checked.'],related=['web-tech/backup-restore-drill','web-tech/expand-and-contract-migrations','web-tech/retention-inventory-and-expiry-workflows']),
 dict(hub=1,path='web-tech/browser-storage-cleanup-on-account-change',title='Browser Storage Cleanup on Account Change',summary='Clear private browser state when identity changes without making client cleanup the only security control.',definition='A browser can hold private data in memory caches, IndexedDB, service-worker caches, object URLs, downloaded files, and restored page history. An account switch or logout must remove or invalidate application-controlled copies tied to the old identity. Storage is origin-scoped, so a generic clear operation can remove unrelated accounts or offline work; design keys and cleanup deliberately. A browser header may help clear supported origin storage after logout, but behavior varies and cannot retract a file already downloaded. The server still must revoke sessions and deny old requests. Client cleanup reduces accidental display after identity changes; it is not a substitute for authorization.',case='Reviewer 29 signs out of organization 6, then reviewer 62 signs in on the same laptop. The case-47 editor still has a memory cache and IndexedDB draft. A back navigation restores the old page and briefly shows the private note before a network check runs. On identity transition, the app clears old account-scoped caches and draft keys, invalidates in-memory queries, revokes object URLs, and replaces the private route. The server denies the old session regardless of browser cleanup. If an unsent offline draft exists, the UI follows an explicit policy for warning or safe removal before switching accounts.',code='function belongsToFormerAccount(cacheKey, formerAccountId) {\n  return cacheKey.startsWith(`account:${formerAccountId}:`);\n}\nconsole.log(belongsToFormerAccount("account:29:case:47", 29));\n// Output: true',implementation='The predicate illustrates key classification; it does not delete storage. Tag every private browser entry with an account and tenant scope, keep a central inventory of memory and persistent stores, and run cleanup when the identity changes. Revoke the server session first or atomically with logout, then clear client caches and leave private content. When supported and appropriate, a site-data clearing response can assist, but test its effect on service workers and other accounts sharing the origin. Protect private HTML with suitable caching directives and revalidate restored pages. Do not promise that downloaded exports or screenshots can be remotely erased.',cost='Scanning n account-scoped keys is O(n) work if the storage API lacks a scoped drop operation. Separate databases or namespaces can make cleanup easier but add storage and migration overhead. Clearing all origin storage is simple but may discard unrelated offline drafts and increase later load times. Revalidating every restored private page adds a network round trip yet prevents stale display after logout. Measure residual private records after switch, cleanup time, and behavior in offline and back-forward restoration. The server authorization check must remain correct even if browser cleanup throws an exception.',failure='Logout invalidates the cookie, but an old tab stays open and its service-worker cache serves a private case page while offline. A second account sees the old note. Inventory and clear private caches, handle restored pages, and avoid caching private HTML as a generic offline fallback. Another defect uses localStorage.clear() on a shared origin, silently deleting a different account’s unsent draft. Scope storage keys and define the account-switch policy. A cleanup exception must not leave the old server session valid; server revocation is the first protection.',drill='Create a memory-cached case, IndexedDB draft, service-worker response, object URL, and downloaded export for reviewer 29. Switch to reviewer 62 and inspect every application-controlled store. Go back, reload offline, and wake a suspended tab; old private content must not render as current. Force one storage deletion to fail and verify server requests remain denied. Test a pending offline draft and follow the chosen warning/removal rule. Record the downloaded file as an explicit limit of browser-side cleanup.',decision='Scope private browser data by identity, clear it on transitions, and enforce server revocation independently.',checks=['Old account data is absent from application-controlled caches after switch.','Restored and offline pages cannot present stale private content as current.','Server denial holds even if client cleanup fails.'],mistakes=['Assuming cookie revocation clears IndexedDB and service-worker caches.','Using a broad origin clear without considering other account drafts.','Claiming downloaded files can be remotely erased.'],related=['web-tech/browser-storage-boundary','web-tech/back-forward-cache-and-restored-state','web-tech/account-recovery-and-session-revocation'])
]
